import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 55 丰：盛大之中仍可能看不清至比较与自测","description":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","frontmatter":{"title":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 55 丰：盛大之中仍可能看不清至比较与自测","description":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","splitFrom":"life/personal/yijing/hexagrams-49-56.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","summary":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价","link":"/life/personal/yijing/hexagrams-49-56-part-02"},"next":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","link":"/life/personal/yijing/hexagrams-57-64"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价","link":"/life/personal/yijing/hexagrams-49-56-part-02"},"next":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","link":"/life/personal/yijing/hexagrams-57-64"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-49-56-part-03.md","filePath":"life/personal/yijing/hexagrams-49-56-part-03.md"}'),o={name:"life/personal/yijing/hexagrams-49-56-part-03.md"};function i(s,t,d,l,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读-四十九至五十六-革、鼎、震、艮、渐、归妹、丰、旅-·-55-丰-盛大之中仍可能看不清至比较与自测" tabindex="-1">六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 55 丰：盛大之中仍可能看不清至比较与自测 <a class="header-anchor" href="#六十四卦详读-四十九至五十六-革、鼎、震、艮、渐、归妹、丰、旅-·-55-丰-盛大之中仍可能看不清至比较与自测" aria-label="Permalink to &quot;六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 55 丰：盛大之中仍可能看不清至比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-49-56">返回分篇目录</a></p><p>这里保留《周易》卦辞、爻辞与《象传》大象的原貌，再用简体中文解释。白话均为现代概括，古注主要取王弼注、孔颖达疏《周易正义》，不是现代逐字译文。遇到异文、难字或不同解释时会注明；引文中的占断属于古代文本，不据以保证事件结果。</p><p>这八卦既有革鼎的制度变化，也有震艮的动静，更有渐、归妹中的婚姻礼制。读古代家庭与政治时，要同时看见思想资源和历史限制；现代借鉴必须说明转换的前提。</p><h2 id="gua-55" tabindex="-1">55 丰：盛大之中仍可能看不清 <a class="header-anchor" href="#gua-55" aria-label="Permalink to &quot;55 丰：盛大之中仍可能看不清 {#gua-55}&quot;">​</a></h2><p><strong>卦符：䷶｜上卦震 ☳（雷、动），下卦离 ☲（火、明）。</strong> 明与动相合，形成丰盛广大；但爻辞反复写正午见星，显示盛大与遮蔽可能并存。</p><p><strong>卦辞原文：</strong></p><blockquote><p>豐：亨。王假之，勿憂，宜日中。</p></blockquote><p><strong>白话概括：</strong> 王者达到丰盛通达的局面，如正午光照广远。《正义》既说要让隐滞者也得通，又据《彖传》提醒日中必斜、月盈会亏；因此“勿忧”不是对永远繁荣的担保，而是要把已有充足用于照顾未被照见之处。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>遇其配主，雖旬无咎，往有尚。</td><td>遇到相配的主者，可以相互成就；“旬”古注有均等之义，不一定是十天，勿据字面推日程。</td></tr><tr><td>六二</td><td>豐其蔀，日中見斗，往得疑疾，有孚發若，吉。</td><td>遮蔽物太盛，正午反见北斗，前往可能受猜疑；以信实打开隔阂。“蔀”读 bù。</td></tr><tr><td>九三</td><td>豐其沛，日中見沬，折其右肱，无咎。</td><td>遮蔽更甚且失去右臂之助，难以担当大事；“沛、沬”有训释争论，不宜强作天象实测。</td></tr><tr><td>九四</td><td>豐其蔀，日中見斗，遇其夷主，吉。</td><td>同处遮暗环境，却遇可相助的同等者；改善条件来自合作，而不是只等待光明自动回来。</td></tr><tr><td>六五</td><td>來章，有慶譽，吉。</td><td>招来有光明德才者，获得庆誉；古注将“章”与明联系，强调让外部能力进入。</td></tr><tr><td>上六</td><td>豐其屋，蔀其家，窺其戶，闃其无人，三歲不覿，凶。</td><td>屋舍盛大却自蔽隔绝，门内空寂；“阒”读 qù，外表规模与实际活力形成强烈反差。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>雷電皆至，豐；君子以折獄致刑。</p></blockquote><p><strong>大象解释：</strong> 明察与果断结合，审断案件、落实刑罚，是古代司法比喻。现代可讨论证据与判断的配合，具体法律必须依现行制度。</p><p><strong>整体读法与误区：</strong> 丰卦最值得注意的不是财富数量，而是光明能否穿过遮蔽。它用盛屋无人纠正“规模越大越成功”，用来章提醒开放接纳。现实可反思信息是否被层层过滤、热闹是否掩盖孤立、充足资源是否惠及真正需要者；不能据日中见斗推断某次日食、市场顶点或个人灾期。</p><p><strong>经传对读：</strong> 卦辞的“日中”与爻辞的“日中见斗”构成反差：同是正午，却可能有光照与遮暗两种状态。九三的右肱又写出失去助力，六五的来章则写接纳外来明者。可以把光照、信息和协助三条线索合读；丰的不足有时恰是不能看见周围，而非物质数量还不够多。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%B1%90" target="_blank" rel="noopener noreferrer">《周易·丰》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E8%B1%90" target="_blank" rel="noopener noreferrer">《周易正义》卷六·丰</a>。</p><h2 id="gua-56" tabindex="-1">56 旅：暂居异处的支持与分寸 <a class="header-anchor" href="#gua-56" aria-label="Permalink to &quot;56 旅：暂居异处的支持与分寸 {#gua-56}&quot;">​</a></h2><p><strong>卦符：䷷｜上卦离 ☲（火），下卦艮 ☶（山）。</strong> 火在山上随草木移动，古注用来比喻不能久留；“旅”首先是失去本居、寄居他方。</p><p><strong>卦辞原文：</strong></p><blockquote><p>旅：小亨，旅貞吉。</p></blockquote><p><strong>白话概括：</strong> 羁旅中能有有限的通达，适合旅居处境的正当行为带来吉。《正义》强调寄居者需要所托，也肯定使旅者安居的治理能力。这使旅卦同时涉及来客的分寸和接纳者的责任，不能只要求弱势客人谨小慎微。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>旅瑣瑣，斯其所取災。</td><td>困在琐细卑下的处境而难免灾患；《正义》还联系卑微劳役，不宜一律译成旅行者小气招灾。</td></tr><tr><td>六二</td><td>旅即次，懷其資，得童僕貞。</td><td>有住处、有资财、有可靠协助，形成旅居的基本支持；“次”为临时住宿处，“僮／童”是异文。</td></tr><tr><td>九三</td><td>旅焚其次，喪其童僕，貞厲。</td><td>住处焚毁、协助者离失，安全基础受损；古注联系寄居而侵权的风险，非对火灾作必然因果解释。</td></tr><tr><td>九四</td><td>旅于處，得其資斧，我心不快。</td><td>暂有停留处与资具，心仍不安；“资斧”有工具、资财等不同解释，物质具备不等于获得归属。</td></tr><tr><td>六五</td><td>射雉一矢亡，終以譽命。</td><td>为射雉损失一箭，最终得到赞誉与命；有限代价与适当表现可以并存，不代表所有损失终会获偿。</td></tr><tr><td>上九</td><td>鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。</td><td>鸟失巢、旅人由笑转哭，又丧牛，表现忽视依托而遭巨变；“易”场所与平易义都有讨论空间。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>山上有火，旅；君子以明慎用刑，而不留獄。</p></blockquote><p><strong>大象解释：</strong> 明察、慎罚，同时不让案件长期拖延。《正义》以火不停留和艮止离明解释，意在审慎与及时兼顾，不是草率速判。</p><p><strong>整体读法与误区：</strong> 与家人相比，旅中的制度、资源和关系更临时；与丰相比，规模收缩而依托更重要。现代可联系迁居、求学、出差和异地工作，先辨基本支持和各方责任。无需把旅浪漫化为必然开阔眼界，也不把所有异乡困难归咎于来客；六二可作为清楚的阅读清单：住处、资源、可信协助是否在场。</p><p><strong>经传对读：</strong>“次、处、巢”都是暂时或本有的依托，却在各爻出现得、失与焚毁的不同结果；资财与僮仆则补充物和人的支持。九四拥有资具而仍不快，尤其使物质安全与归属感分开。读者可先列出这些支撑，再讨论古注的处世建议，避免只把旅人所有困难概括为不够谦顺。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%97%85" target="_blank" rel="noopener noreferrer">《周易·旅》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E6%97%85" target="_blank" rel="noopener noreferrer">《周易正义》卷六·旅</a>。</p><h2 id="比较与自测" tabindex="-1">比较与自测 <a class="header-anchor" href="#比较与自测" aria-label="Permalink to &quot;比较与自测 {#比较与自测}&quot;">​</a></h2><ol><li>革与鼎为什么连读？“改变旧规则”与“建立可供养的新秩序”各需什么条件？</li><li>震的惊惧和艮的停止，哪些能帮助判断，哪些反会造成僵滞？</li><li>渐与归妹的婚姻背景是什么？现代引用时应明确舍弃哪些古代等级安排？</li><li>丰上六的盛屋与旅上九的焚巢，分别怎样揭示居所背后的关系问题？</li></ol><p>继续阅读：<a href="/life/personal/yijing/hexagrams-57-64">第五十七至六十四卦</a> · 返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',33)])])}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
